/**
 * Clean, lightweight, self-contained SweetAlert2 compatible notification library.
 * Zero-dependency, no external assets, secure against supply-chain injection.
 */
(function(window) {
    'use strict';

    function createBackdrop() {
        let bd = document.getElementById('swal-backdrop');
        if (!bd) {
            bd = document.createElement('div');
            bd.id = 'swal-backdrop';
            bd.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:99999;display:flex;align-items:center;justify-content:center;padding:16px;';
            document.body.appendChild(bd);
        }
        return bd;
    }

    function createToastContainer() {
        let tc = document.getElementById('swal-toast-container');
        if (!tc) {
            tc = document.createElement('div');
            tc.id = 'swal-toast-container';
            tc.style.cssText = 'position:fixed;top:20px;right:20px;z-index:100000;display:flex;flex-direction:column;gap:10px;pointer-events:none;max-width:380px;width:100%;';
            document.body.appendChild(tc);
        }
        return tc;
    }

    const icons = {
        success: '✓',
        error: '✕',
        warning: '⚠',
        info: 'ℹ',
        question: '?'
    };

    const iconColors = {
        success: '#10b981',
        error: '#ef4444',
        warning: '#f59e0b',
        info: '#0ea5e9',
        question: '#6366f1'
    };

    window.Swal = {
        fire: function(options) {
            return new Promise(function(resolve) {
                if (typeof options === 'string') {
                    options = { title: options };
                }
                options = options || {};

                if (options.toast) {
                    const tc = createToastContainer();
                    const toast = document.createElement('div');
                    toast.style.cssText = 'pointer-events:auto;background:#fff;border-radius:10px;box-shadow:0 10px 25px rgba(0,0,0,0.15);padding:14px 18px;display:flex;align-items:flex-start;gap:12px;border-left:4px solid ' + (iconColors[options.icon] || '#006b91') + ';transition:opacity 0.25s ease;';

                    const iconEl = document.createElement('div');
                    iconEl.style.cssText = 'font-weight:bold;font-size:18px;color:' + (iconColors[options.icon] || '#006b91') + ';line-height:1.2;';
                    iconEl.textContent = icons[options.icon] || '•';
                    toast.appendChild(iconEl);

                    const bodyEl = document.createElement('div');
                    bodyEl.style.cssText = 'flex:1;';
                    if (options.titleText || options.title) {
                        const titleEl = document.createElement('div');
                        titleEl.style.cssText = 'font-weight:700;font-size:14px;color:#1e293b;';
                        titleEl.textContent = options.titleText || options.title;
                        bodyEl.appendChild(titleEl);
                    }
                    if (options.text) {
                        const textEl = document.createElement('div');
                        textEl.style.cssText = 'font-size:13px;color:#64748b;margin-top:2px;';
                        textEl.textContent = options.text;
                        bodyEl.appendChild(textEl);
                    }
                    toast.appendChild(bodyEl);
                    tc.appendChild(toast);

                    setTimeout(function() {
                        toast.style.opacity = '0';
                        setTimeout(function() {
                            if (toast.parentNode) toast.parentNode.removeChild(toast);
                            resolve({ isConfirmed: true });
                        }, 250);
                    }, options.timer || 3500);
                    return;
                }

                // Modal dialog
                const bd = createBackdrop();
                bd.replaceChildren();

                const box = document.createElement('div');
                box.style.cssText = 'background:#fff;border-radius:14px;box-shadow:0 20px 40px rgba(0,0,0,0.2);max-width:460px;width:100%;padding:28px;text-align:center;box-sizing:border-box;';

                if (options.icon) {
                    const iconWrap = document.createElement('div');
                    iconWrap.style.cssText = 'width:56px;height:56px;margin:0 auto 16px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:26px;font-weight:bold;color:#fff;background:' + (iconColors[options.icon] || '#006b91') + ';';
                    iconWrap.textContent = icons[options.icon] || 'ℹ';
                    box.appendChild(iconWrap);
                }

                if (options.titleText || options.title) {
                    const titleEl = document.createElement('h3');
                    titleEl.style.cssText = 'margin:0 0 10px;font-size:19px;font-weight:700;color:#0f172a;';
                    titleEl.textContent = options.titleText || options.title;
                    box.appendChild(titleEl);
                }

                if (options.html) {
                    const htmlEl = document.createElement('div');
                    htmlEl.style.cssText = 'font-size:14px;color:#475569;margin-bottom:20px;text-align:left;line-height:1.5;';
                    htmlEl.innerHTML = options.html;
                    box.appendChild(htmlEl);
                } else if (options.text) {
                    const textEl = document.createElement('p');
                    textEl.style.cssText = 'font-size:14px;color:#475569;margin:0 0 20px;line-height:1.5;';
                    textEl.textContent = options.text;
                    box.appendChild(textEl);
                }

                const btn = document.createElement('button');
                btn.type = 'button';
                btn.style.cssText = 'background:' + (options.confirmButtonColor || '#006b91') + ';color:#fff;border:none;padding:10px 24px;border-radius:8px;font-weight:600;font-size:15px;cursor:pointer;min-width:110px;';
                btn.textContent = options.confirmButtonText || 'Đồng ý';
                btn.onclick = function() {
                    if (bd.parentNode) bd.parentNode.removeChild(bd);
                    resolve({ isConfirmed: true });
                };
                box.appendChild(btn);

                bd.appendChild(box);
            });
        }
    };
})(window);
